const tabId = 1148881640;

const analysis = await browserjs(tabId, () => {
  const items = document.querySelectorAll(".arxiv-result");
  const parsed = Array.from(items).map(item => {
    const titleEl = item.querySelector(".title");
    const authorsEl = item.querySelector(".authors");
    const abstractEl = item.querySelector(".abstract-full") || item.querySelector(".abstract-short");
    const tagsEl = item.querySelector(".tags");
    const dateText = Array.from(item.querySelectorAll("p.is-size-7")).find(p => p.textContent.includes("Submitted"))?.textContent.trim();
    const linkEl = item.querySelector(".list-title a");
    const tags = Array.from(tagsEl?.querySelectorAll(".tag") || []).map(t => t.textContent.trim());

    return {
      id: linkEl?.textContent?.trim(),
      url: linkEl?.href,
      title: titleEl?.textContent?.trim().replace(/\s+/g, ' ').replace(/^Title:\s*/, ''),
      authors: authorsEl?.textContent?.trim().replace(/\s+/g, ' ').replace(/^Authors:\s*/, ''),
      submissionDate: dateText,
      tags,
      isMath: tags.some(t => t.startsWith("math.")),
      isCS: tags.some(t => t.startsWith("cs.")),
      abstractSnippet: abstractEl?.textContent?.trim().replace(/\s+/g, ' ').replace(/△ Less$/, '').replace(/▽ More$/, '').slice(0, 200) + "..."
    };
  });

  const mathPapers = parsed.filter(p => p.isMath);
  const csPapers = parsed.filter(p => p.isCS);

  return {
    totalOnPage: parsed.length,
    mathCountOnPage: mathPapers.length,
    csCountOnPage: csPapers.length,
    sampleMath: mathPapers.slice(0, 5),
    sampleCS: csPapers.slice(0, 5)
  };
});

console.log("Analysis on page 1:", JSON.stringify(analysis, null, 2));

